-- ============================================================================
-- SZTAB — Migracja 004: Wysyłka DM (masowa kampania Instagram).
-- Uruchom PO migracjach 001–003.
--
-- Po co osobna tabela zamiast wrzucenia 219 kont do crm_leads: masówka
-- zalałaby kolejkę Outbound i listę leadów. Tu żyje tylko checklista wysyłki
-- ze wspólnym stanem dla obu osób; kto ODPOWIE, awansuje jednym kliknięciem
-- do crm_leads i dalej idzie normalnym pipeline'em.
-- ============================================================================

create table if not exists crm_dm_blitz (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 160),
  city text,
  niche text not null,
  instagram text not null unique,
  followers int check (followers is null or followers >= 0),
  -- Gotowa wiadomość z podstawioną nazwą lokalu — przycisk "Kopiuj DM" bierze ją 1:1.
  dm_text text not null,
  campaign text not null default 'dm-ig-2026-08',
  sent_at timestamptz,
  sent_by text,
  -- Ustawiane przy awansie do CRM ("odpowiedział") — chroni przed drugim awansem.
  lead_id uuid references crm_leads(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_crm_dm_blitz_niche on crm_dm_blitz(niche, sent_at);

drop trigger if exists trg_crm_dm_blitz_updated on crm_dm_blitz;
create trigger trg_crm_dm_blitz_updated
before update on crm_dm_blitz
for each row execute function crm_touch_updated_at();

alter table crm_dm_blitz enable row level security;
revoke all on crm_dm_blitz from anon, authenticated;

-- ----------------------------------------------------------------------------
